SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'kennwert_quellen', 'Kostenkennwert-Quellen (je Quelle Kostengruppe, Quelle, Stand, Region, Preisstand, Standard)', 'json', NULL, false, '§4.2.7', 'Plan 3: Zeilen je Kennwert-Quelle („the sources of the cost parameters used must be stated“); Anzahl → kennwert_quellen_count (DIN-276-07-D1). Die sieben Einzelwerte KKW_* sind Ablösekandidaten (din276-D-8).', 'imported_unverified', 'The cost calculation methods used in the cost calculation and the sources of the cost parameters used must be stated.', 'register', '{"title":"Kostenkennwert-Quellen","subtitle":"§4.2.7 — je Quelle Kostengruppe, Quelle, Stand, Region, Preisstand, Standard","add_label":"+ Quelle","placement":"section","columns":[{"key":"kg","label":"Kostengruppe (Tab. 1)","type":"lookup_key","lookup":{"table_code":"TABLE1","group_by":"group_label"}},{"key":"bezeichnung","label":"Bezeichnung (Tab. 1)","type":"lookup_value","lookup":{"table_code":"TABLE1","key_column":"kg","value":"designation"}},{"key":"quelle","label":"Quelle","type":"text","required":true,"datalist":["BKI","Vergleichsprojekt","eigene Datenbank"]},{"key":"stand","label":"Datenstand","type":"date"},{"key":"region","label":"Region / Regionalfaktor","type":"text"},{"key":"preisstand","label":"Preisstand (Index)","type":"text"},{"key":"standard","label":"Standard","type":"text"},{"key":"bemerkung","label":"Bemerkung","type":"text"}],"footer":["kennwert_quellen_count"],"note":"The cost calculation methods used in the cost calculation and the sources of the cost parameters used must be stated. Die sieben Einzelwerte KKW_* bleiben bis din276-D-8."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
