SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'kg5_positionen', 'Kostenpositionen KG 500 (je Position KG, Menge, Einheit, Kennwert, Kosten)', 'json', NULL, false, '§5.4 Table 1, §6 Tables 2–4, §3.13', 'Plan 3: Zeilen je Kostenposition der KG 500 (Tab.-1-Zeile als Zeilenschlüssel; Bezugseinheit aus Tab. 2 / 3 / 4); Σ Kosten → kg5_positionen_sum, Σ je KG 2. Ebene → kg_NN0_from_rows (DIN-276-13-D-Zeilen). Die getippten Einzelwerte kg_NNN und die Summengleichungen KG5-xx bleiben (din276-D-3).', 'imported_unverified', 'The cost breakdown is shown in Table 1. The goods, services, taxes and duties listed in the "Notes" column of this table are examples of the respective cost group. The list is not exhaustive. — Value that represents the ratio of costs to a reference unit', 'register', '{"title":"Kostenpositionen KG 500 (Menge × Kennwert = Kosten)","subtitle":"Tab. 1 / §6 — je Zeile eine Kostengruppe der Tab. 1 mit Menge, Bezugseinheit (Tab. 4 → Tab. 3 → Tab. 2, §6.2), Kostenkennwert und Kosten","add_label":"+ Kostenposition","placement":"section","columns":[{"key":"kg","label":"Kostengruppe (Tab. 1)","type":"lookup_key","lookup":{"table_code":"TABLE1","group_by":"group_label"},"required":true},{"key":"bezeichnung","label":"Bezeichnung (Tab. 1)","type":"lookup_value","lookup":{"table_code":"TABLE1","key_column":"kg","value":"designation"}},{"key":"tab4_nr","label":"Tab.-4-Position (nur KG 4xx)","type":"text","placeholder":"z. B. 1","aria_label":"Nummer der Position in Tabelle 4 (nur für Kostengruppen 4xx)"},{"key":"ebene1","label":"KG 1. Ebene","type":"derived","expr":"lookup(''TABLE1'', kg, ''kg1'')"},{"key":"ebene2","label":"KG 2. Ebene","type":"derived","expr":"if(lookup(''TABLE1'', kg, ''level'') == 1, ''-'', lookup(''TABLE1'', kg, ''kg2''))"},{"key":"tab4_kg_einheit","label":"Einheit der KG (Tab. 4)","type":"derived","expr":"lookup(''TABLE4'', kg, ''0'', ''unit'')"},{"key":"menge","label":"Menge","type":"number","min":0},{"key":"einheit","label":"Einheit (Tab. 2 / 3 / 4)","type":"derived","expr":"if(tab4_nr IS NULL, if(ebene1 == ''KG 400'', if(tab4_kg_einheit IS NULL, lookup(''TABLE2'', lookup(''TABLE1'', kg, ''kg1_key''), ''unit''), tab4_kg_einheit), if(ebene1 == ''KG 300'', lookup(''TABLE3'', kg, ''unit''), lookup(''TABLE2'', lookup(''TABLE1'', kg, ''kg1_key''), ''unit''))), lookup(''TABLE4'', kg, tab4_nr, ''unit''))"},{"key":"kennwert","label":"Kostenkennwert","type":"number","unit":"EUR/Einheit","min":0},{"key":"kosten_calc","label":"Menge × Kennwert","type":"derived","expr":"menge * kennwert"},{"key":"kosten_eur","label":"Kosten","type":"number","unit":"EUR","required":true,"min":0},{"key":"abw","label":"Kosten ≠ Menge × Kennwert","type":"derived","expr":"if(menge IS NULL OR kennwert IS NULL, 0, if(abs(kosten_eur - menge * kennwert) < 0.005, 0, 1))","display":"badge","value_labels":{"0":"ok","1":"abweichend"}},{"key":"im_kg","label":"Position gehört zu KG 500","type":"derived","expr":"if(ebene1 == ''KG 500'', 1, 0)","display":"badge","value_labels":{"0":"nein","1":"ja"}},{"key":"hinweis","label":"Hinweise (Tab. 1)","type":"lookup_value","lookup":{"table_code":"TABLE1","key_column":"kg","value":"notes"}}],"footer":["kg5_positionen_sum","kg5_positionen_count","kg5_positionen_fremd","kg5_positionen_abweichend","kg_510_from_rows","kg_520_from_rows","kg_530_from_rows","kg_540_from_rows","kg_550_from_rows","kg_560_from_rows","kg_570_from_rows","kg_580_from_rows","kg_590_from_rows"],"note":"The cost breakdown is shown in Table 1. The goods, services, taxes and duties listed in the \"Notes\" column of this table are examples of the respective cost group. The list is not exhaustive. It is recommended that the quantities and reference units in Table 2 be used for cost parameters of the cost groups of the first level of the cost breakdown in Table 1. Unless further specifications are made under 6.3 and Table 3 as well as under 6.4 and Table 4, this also applies to the respective cost groups of the second and third level of the cost breakdown. Zeilen anderer Kostengruppen werden gekennzeichnet und in keiner Summe gezählt. Die Einzelwerte kg_NNN dieses Arbeitsblatts bleiben bis din276-D-3."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
