FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kg6_positionen_sum') AND w.code = 'DIN-276-14' AND s.code = 'DIN-276';
