SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'vergabeeinheiten', 'Vergabeeinheiten (je Einheit Gewerk, Kostengruppe, Angebot / Auftrag / Rechnung, Kostenstand)', 'json', NULL, false, '§4.3.5, §4.3.6', 'Plan 3: Zeilen je Vergabeeinheit („organised according to the award units … so that the offers, orders and invoices … can be compiled, checked and compared“); Σ zum Kostenstand → KA_kostenstand_calc (DIN-276-21-D1), Anzahl je Kostenstand → KA_angebote_count / KA_auftraege_count / KA_rechnungen_count (-D3 … D5). Die Einzelwerte KA_angebote_eingegangen / KA_kostenstatus / KA_vergabeeinheiten_struktur sind Ablösekandidaten (din276-D-5 / T-1).', 'imported_unverified', 'Irrespective of the type of determination or the cost determination procedure selected, the costs determined must also be organised according to the award units intended for the construction project so that the offers, orders and invoices (including supplements) can be compiled, checked and compared in an up-to-date manner. — The cost estimate is prepared in several steps in accordance with the project sequence selected for the construction project by compiling the costs on the basis of the current cost status (offer, order or invoice).', 'register', '{"title":"Vergabeeinheiten (Angebot / Auftrag / Rechnung)","subtitle":"§4.3.5 / §4.3.6 — je Vergabeeinheit Gewerk, Kostengruppe, Angebots-, Auftrags-, Rechnungssumme und Kostenstand","add_label":"+ Vergabeeinheit","placement":"section","columns":[{"key":"label","label":"Vergabeeinheit","type":"text","required":true},{"key":"gewerk","label":"Gewerk / Leistungsbereich","type":"text"},{"key":"kg","label":"Kostengruppe (Tab. 1)","type":"lookup_key","lookup":{"table_code":"TABLE1","group_by":"group_label"}},{"key":"bezeichnung","label":"Bezeichnung (Tab. 1)","type":"lookup_value","lookup":{"table_code":"TABLE1","key_column":"kg","value":"designation"}},{"key":"angebot_eur","label":"Angebot","type":"number","unit":"EUR","min":0},{"key":"auftrag_eur","label":"Auftrag","type":"number","unit":"EUR","min":0},{"key":"rechnung_eur","label":"Rechnung","type":"number","unit":"EUR","min":0},{"key":"status","label":"Kostenstand","type":"enum","options":["angebot","auftrag","rechnung"],"option_labels":{"angebot":"Angebot (offer)","auftrag":"Auftrag (order)","rechnung":"Rechnung (invoice)"},"required":true,"discriminator":true},{"key":"aktuell","label":"Betrag zum Kostenstand","type":"derived","expr":"if(status == ''rechnung'', rechnung_eur, if(status == ''auftrag'', auftrag_eur, angebot_eur))"}],"footer":["KA_kostenstand_calc","vergabeeinheiten_count","KA_angebote_count","KA_auftraege_count","KA_rechnungen_count"],"note":"Irrespective of the type of determination or the cost determination procedure selected, the costs determined must also be organised according to the award units intended for the construction project so that the offers, orders and invoices (including supplements) can be compiled, checked and compared in an up-to-date manner. The cost estimate is prepared in several steps in accordance with the project sequence selected for the construction project by compiling the costs on the basis of the current cost status (offer, order or invoice). Die Einzelwerte KA_angebote_eingegangen / KA_kostenstatus / KA_vergabeeinheiten_struktur bleiben bis din276-D-5 / T-1."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
